steps.script:
var AD = load("res://scripts/AIDecisionMaker.gd")
var uid = "U_TWC_TEST"
var snap = GameState.create_snapshot()
var su = snap.units[uid]
var enemies = AD._get_enemy_units(snap, 1)
AD._move_waypoint_log = {}
AD._move_shape_notes = []
var T = AD._get_unit_centroid(su) + Vector2.RIGHT.rotated(deg_to_rad(120)) * 560.0
var dests = AD._compute_movement_toward_target(su, uid, T, 12.0, snap, enemies, 0.0, [], AD._get_objectives(snap))
var d = {"type": "BEGIN_NORMAL_MOVE", "actor_unit_id": uid, "_ai_model_destinations": dests, "_ai_description": "TWC dogleg normal move"}
AD._attach_move_waypoints(d)
var out = {"dests": dests, "wps": d.get("_ai_model_waypoints"), "notes": AD._move_shape_notes.duplicate()}
var r = NetworkIntegration.route_action({"type": "BEGIN_NORMAL_MOVE", "actor_unit_id": uid, "player": 1})
var ph = PhaseManager.current_phase_instance
if ph.has_pending_stratagem_window():
	var w = ph.get_pending_stratagem_window()
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
var was = AIPlayer.enabled
AIPlayer.enabled = true
AIPlayer._execute_ai_movement(1, d)
AIPlayer.enabled = was
var u = GameState.state.units[uid]
var pos = []
for m in u.models:
	pos.append(m.position)
out["pos"] = pos
out["moved"] = u.flags.get("moved")
var ok = bool(u.flags.get("moved", false))
for mid in dests:
	var m = null
	for mm in u.models:
		if str(mm.id) == mid:
			m = mm
	var want = Vector2(dests[mid][0], dests[mid][1])
	if Vector2(m.position.x, m.position.y).distance_to(want) > 1.0:
		ok = false
return ok and d.get("_ai_model_waypoints", {}).size() == 3
